import type { Q } from "../types";

export const computerScience2: Q[] = [
  // ---- Systems design ----
  { t: "Load balancing strategies", p: "Compare round robin, least connections and consistent hashing for load balancing, and when sticky sessions are needed.", d: 2, tp: "systems-design", tp2: "networking", i: "Round robin cycles through servers, simple and fair for similar requests. Least connections sends traffic to the server with the fewest active requests, better when request durations vary. Consistent hashing maps keys to servers on a ring so adding or removing a server moves only a small share of keys, good for caches and sharded state. Sticky sessions route a user to the same server for local state, which hurts balance and failover, so storing session state externally is preferred.", c: ["Round robin for uniform requests", "Least connections for variable durations", "Consistent hashing limits reshuffling", "Sticky sessions versus external session state"], k: ["Health checks remove failed servers", "Layer 4 versus layer 7 balancing differ in routing detail"], m: ["Keeping per-user state only in one server's memory"] },
  { t: "CAP theorem and consistency models", p: "Explain the CAP theorem and what trade-off a system makes during a network partition.", d: 3, tp: "systems-design", tp2: "databases", i: "During a network partition, a distributed system must choose between consistency (every read sees the latest write, so some requests must be refused) and availability (every request gets a response, possibly stale). Without a partition both can be offered, and latency also trades against consistency (PACELC). Strong consistency suits finances and inventory, eventual consistency suits feeds and caches, and models in between include read-your-writes and causal consistency.", c: ["Partition forces a choice between consistency and availability", "Without partitions both can hold, but latency trades", "Strong versus eventual consistency use cases", "Intermediate models such as causal consistency"], k: ["Quorum reads and writes tune the trade-off", "Conflict resolution is needed for eventual consistency"], m: ["Thinking CAP means choosing two of three at all times"] },
  { t: "Design a rate limiter", p: "Design a rate limiter for an API and compare token bucket with fixed window counters.", d: 2, tp: "systems-design", tp2: "web-apis", i: "A token bucket holds up to a burst capacity and refills at a steady rate; each request consumes a token and is rejected or delayed when empty, allowing bursts while enforcing the average rate. Fixed window counters count requests per time window, simple but allow double the rate at window boundaries, and sliding windows reduce this. Distributed limiters keep counters in a shared fast store such as Redis with atomic operations, return headers like Retry-After, and decide whether to fail open or closed on store failure.", c: ["Token bucket allows bursts at a steady average rate", "Fixed window boundary problem", "Shared store with atomic operations for distributed limits", "Return clear rejection responses and handle store failure"], k: ["Limit by user, key or IP depending on the threat", "Clock differences between servers matter"], m: ["Keeping counters in local memory behind many servers"] },
  { t: "Message queues and asynchronous processing", p: "Why decouple services with a message queue and what delivery issues must you handle?", d: 2, tp: "systems-design", i: "Queues buffer work between producers and consumers, absorbing spikes, letting components scale and fail independently and enabling retries. Delivery is usually at-least-once, so consumers must be idempotent to handle duplicates, and ordering may be guaranteed only per partition. Handle poison messages with dead-letter queues, apply backpressure, monitor queue depth and lag, and choose between queues (work distribution) and logs (replayable streams).", c: ["Decouples and absorbs spikes", "At-least-once delivery needs idempotent consumers", "Ordering per partition and dead-letter queues", "Backpressure and monitoring"], k: ["Exactly-once is hard and usually emulated", "Retries need backoff to avoid overload"], m: ["Assuming messages arrive exactly once and in order"] },
  { t: "Database sharding and partitioning", p: "How do you shard a database, and what problems does sharding create?", d: 3, tp: "systems-design", tp2: "databases", i: "Partition data across nodes by a shard key using hash or range partitioning, with consistent hashing easing rebalancing. Benefits are capacity and throughput scaling. Problems include hot shards from skewed keys, cross-shard joins and transactions (needing distributed protocols or denormalisation), rebalancing as data grows, operational complexity and choosing a key that matches access patterns. Try vertical scaling, read replicas and caching first.", c: ["Hash or range partition by a shard key", "Consistent hashing for rebalancing", "Hot shards and cross-shard operations are problems", "Exhaust simpler scaling options first"], k: ["Shard key choice is hard to change later", "Directory services map keys to shards"], m: ["Sharding by a key that concentrates traffic"] },
  { t: "Idempotency in distributed APIs", p: "What is idempotency and how do you implement it for a payment API that clients may retry?", d: 3, tp: "systems-design", tp2: "web-apis", i: "An operation is idempotent if repeating it has the same effect as doing it once. Clients send a unique idempotency key with the request; the server stores the key with the result in the same transaction as the operation, and on a repeat returns the stored result instead of executing again. This lets clients retry safely after timeouts. Keys expire after a window, and concurrent duplicates are handled with locks or unique constraints.", c: ["Repeating has the same effect as once", "Client-generated idempotency key", "Store key and result atomically with the operation", "Concurrent duplicates handled with uniqueness"], k: ["GET, PUT and DELETE are idempotent by definition", "Network timeouts make retries unavoidable"], m: ["Retrying a non-idempotent charge without a key"] },
  { t: "Designing a notification system", p: "Outline an architecture for sending millions of notifications by email, SMS and push.", d: 3, tp: "systems-design", i: "Producers publish events to a queue, a notification service applies user preferences, templates and rate limits, then routes to channel-specific workers that call providers, with retries, exponential backoff, dead-letter handling and fallback providers. Deduplicate with idempotency keys, track delivery status via callbacks, prioritise transactional messages over marketing, batch where useful and respect opt-outs and regulations. Scale workers independently per channel.", c: ["Queue-based event ingestion", "Preferences, templates and rate limiting", "Channel workers with retries and fallback", "Deduplication, status tracking and priorities"], k: ["Provider rate limits shape the design", "Observability of delivery rates is essential"], m: ["Sending synchronously inside the user request"] },
  { t: "Caching strategies and cache invalidation", p: "Compare cache-aside, write-through and write-back caching and the consistency risks of each.", d: 3, tp: "systems-design", i: "Cache-aside loads data on a miss and the application writes to the database then invalidates or updates the cache, simple but with a window of staleness. Write-through writes to cache and database together, giving consistent reads at higher write latency. Write-back writes to cache first and persists later, fastest but risking loss of data on cache failure. Add TTLs, guard against stampedes on hot keys and monitor hit rate.", c: ["Cache-aside with invalidation", "Write-through for consistency", "Write-back for speed with durability risk", "TTLs, stampede protection and monitoring"], k: ["Invalidation is the hard part", "Cache keys must include all relevant parameters"], m: ["Updating the cache and database in a non-atomic way and assuming consistency"] },
  { t: "Content delivery networks and edge caching", p: "How does a CDN improve latency and what are the cache control considerations?", d: 2, tp: "systems-design", tp2: "networking", i: "A CDN serves content from edge servers close to users, reducing round-trip latency, offloading the origin and absorbing traffic spikes, with TLS terminated at the edge. Caching is controlled by headers (Cache-Control max-age, ETag, Vary), versioned asset URLs enable long caching with instant updates, and purge APIs remove stale content. Dynamic and personalised content needs care with cache keys and private data.", c: ["Edge servers reduce latency and origin load", "Cache-Control, ETag and Vary headers", "Versioned URLs for long caching", "Care with personalised content"], k: ["Cache hit ratio drives benefit", "Origin shielding reduces load on misses"], m: ["Caching private responses publicly"] },
  { t: "Designing for high availability and failover", p: "What does it take to remove single points of failure from a web service?", d: 2, tp: "systems-design", tp2: "testing-reliability", i: "Run multiple instances behind load balancers across availability zones, replicate data with automatic failover, keep services stateless, use health checks and automatic replacement, ensure dependencies (DNS, databases, queues) are redundant too, and test failover regularly with chaos experiments. Define availability targets (SLOs), because each extra nine costs disproportionately more, and plan for partial degradation.", c: ["Multiple instances across zones", "Replicated data with automatic failover", "Stateless services and health checks", "Redundant dependencies and failover testing"], k: ["Redundancy without testing often fails", "Shared fate dependencies hide single points of failure"], m: ["Deploying redundant servers but a single database"] },
  { t: "Event sourcing and CQRS basics", p: "What are event sourcing and CQRS, and what complexity do they add?", d: 3, tp: "systems-design", tp2: "databases", i: "Event sourcing stores a sequence of immutable events as the source of truth and derives current state by replaying them, giving a full audit trail and the ability to rebuild views. CQRS separates the write model (commands) from read models (queries), allowing each to be optimised and scaled independently. Costs are eventual consistency between write and read sides, event schema evolution, more moving parts and a steeper learning curve, so use them where audit or independent scaling justify it.", c: ["Events as the source of truth", "Rebuild state by replaying events", "CQRS separates write and read models", "Complexity: eventual consistency and schema evolution"], k: ["Snapshots speed up replay", "Not suitable for simple CRUD applications"], m: ["Applying event sourcing to every service"] },
  { t: "Observability: logs, metrics and traces", p: "How do logs, metrics and distributed traces differ and why do you need all three?", d: 2, tp: "testing-reliability", tp2: "systems-design", i: "Metrics are numeric time series (rates, latencies, saturation) cheap to store and good for dashboards and alerts. Logs are detailed event records that explain what happened in a specific case. Traces follow a single request across services with timing for each span, locating where latency or errors arise. Together they let you detect a problem with metrics, localise it with traces and diagnose it with logs, using correlation IDs to connect them.", c: ["Metrics for trends and alerting", "Logs for detailed events", "Traces for request paths across services", "Correlation IDs link them"], k: ["High-cardinality labels are costly in metrics", "Structured logs are easier to query"], m: ["Relying on logs alone to monitor a distributed system"] },
  { t: "Back-of-the-envelope capacity estimation", p: "A service handles 50 million daily active users each making 10 requests per day. Estimate peak QPS and storage for 1 KB records written per request.", d: 2, tp: "systems-design", i: "Total requests per day are 5×10⁸. Average QPS is 5×10⁸/86,400, about 5,800 per second, and peak is typically 2 to 5 times average, so about 12,000 to 30,000 QPS. If each request writes a 1 KB record, daily storage is about 500 GB, around 180 TB per year before replication, and with three replicas about 540 TB. State assumptions, check against cache hit rates and read/write mix, and size with headroom.", c: ["Daily requests of 5×10⁸", "Average QPS about 5,800 and peak a few times higher", "Storage 500 GB per day and roughly 180 TB per year", "State assumptions and include replication and headroom"], k: ["Orders of magnitude matter more than exact figures", "Peak-to-average ratio depends on traffic patterns"], m: ["Planning for average QPS only"] },
  // ---- Concurrency & OS ----
  { t: "Mutexes, semaphores and condition variables", p: "Distinguish a mutex, a semaphore and a condition variable and give a use for each.", d: 2, tp: "concurrency-os", i: "A mutex provides mutual exclusion over a critical section, owned by one thread at a time. A semaphore maintains a count and allows up to N concurrent holders or signals between threads, such as limiting connections in a pool. A condition variable lets threads wait until a predicate becomes true, always used with a mutex and in a loop that re-checks the predicate because of spurious wakeups, as in a producer-consumer queue.", c: ["Mutex: exclusive access", "Semaphore: counting permits or signalling", "Condition variable: wait for a predicate with a mutex", "Re-check the predicate in a loop"], k: ["Always release locks, using RAII or finally", "Holding locks across blocking calls is risky"], m: ["Using if instead of while around a condition wait"] },
  { t: "Race conditions and data races", p: "Define a race condition and a data race, and explain how you would find and fix one.", d: 2, tp: "concurrency-os", i: "A data race is concurrent unsynchronised access to the same memory where at least one is a write, which is undefined behaviour in many languages. A race condition is a broader bug where correctness depends on timing or interleaving, even with individually atomic operations, such as check-then-act sequences. Find them with thread sanitisers, stress tests and code review of shared state, and fix by synchronising with locks or atomics, using immutable or thread-confined data or message passing.", c: ["Data race: unsynchronised concurrent access with a write", "Race condition: correctness depends on timing", "Thread sanitisers and stress tests find them", "Locks, atomics, immutability or message passing fix them"], k: ["Check-then-act needs atomic compound operations", "Races can be rare and hard to reproduce"], m: ["Assuming reads without locks are harmless"] },
  { t: "Deadlock, livelock and starvation", p: "Distinguish deadlock, livelock and starvation, and describe prevention strategies.", d: 2, tp: "concurrency-os", i: "Deadlock is threads permanently blocked waiting on each other, requiring mutual exclusion, hold and wait, no preemption and circular wait. Livelock is threads actively changing state in response to each other without progress, and starvation is a thread never getting the resource because others are favoured. Prevent deadlock with a global lock ordering, timeouts, try-locks and avoiding nested locks, and starvation with fair locks or priorities that age.", c: ["Deadlock needs the four Coffman conditions", "Livelock is activity without progress", "Starvation is indefinite denial of a resource", "Lock ordering, timeouts and fair locking"], k: ["Thread dumps reveal deadlocks", "Reducing lock scope reduces risk"], m: ["Retrying immediately in lockstep, causing livelock"] },
  { t: "Threads versus async I/O and event loops", p: "When is an event-loop model preferable to a thread per request, and what are its limits?", d: 3, tp: "concurrency-os", tp2: "web-apis", i: "A thread per request is simple but each thread costs memory and context switches, so it struggles with tens of thousands of mostly idle connections. An event loop multiplexes many connections on few threads using non-blocking I/O (epoll), handling each readiness event with a callback or coroutine, ideal for I/O-bound workloads. Its limits are that CPU-heavy or blocking work stalls the loop, so offload it to worker threads, and code structure can be harder to follow.", c: ["Threads cost memory and context switches", "Event loops multiplex connections with non-blocking I/O", "Best for I/O-bound workloads", "Blocking or CPU-heavy work stalls the loop"], k: ["epoll and kqueue notify readiness", "Async/await makes the style more readable"], m: ["Running blocking calls inside an event loop callback"] },
  { t: "Virtual memory, paging and thrashing", p: "What happens on a page fault and why does thrashing occur?", d: 2, tp: "concurrency-os", tp2: "memory-systems", i: "A page fault occurs when a process accesses a virtual page not in physical memory: the OS finds the page on disk (or allocates a zero page), selects a victim frame if memory is full, loads the page, updates the page table and restarts the instruction. Thrashing happens when the combined working sets exceed physical memory, so the system spends most of its time swapping pages rather than computing. Fixes are reducing the load, adding memory or using better page replacement.", c: ["Fault handler loads the page and updates the page table", "Victim selection when memory is full", "Thrashing when working sets exceed memory", "Reduce load or add memory"], k: ["Working set model describes needed pages", "SSDs reduce but do not remove the cost"], m: ["Thinking more swap space fixes insufficient memory"] },
  { t: "CPU scheduling algorithms", p: "Compare round robin, priority and multilevel feedback queue scheduling.", d: 2, tp: "concurrency-os", i: "Round robin gives each process a time slice in turn, fair and good for interactive systems, with quantum size balancing responsiveness and context switch overhead. Priority scheduling runs the highest-priority task first, which risks starvation unless aging raises waiting tasks. A multilevel feedback queue moves processes between queues based on behaviour, favouring short interactive jobs and demoting CPU-bound ones, approximating shortest-job-first without knowing job lengths.", c: ["Round robin and time quantum", "Priority scheduling with starvation and aging", "Multilevel feedback queues adapt to behaviour", "Trade-offs between responsiveness and throughput"], k: ["Real-time systems use deadline-based schedulers", "Context switch cost limits very small quanta"], m: ["Setting the quantum extremely small"] },
  { t: "System calls and kernel versus user mode", p: "Why does an operating system separate kernel and user mode and what happens during a system call?", d: 2, tp: "concurrency-os", tp2: "security", i: "Hardware privilege levels stop user programs from directly accessing devices or other processes' memory, so a faulty or malicious program cannot compromise the system. A system call uses a trap instruction to switch into kernel mode at a controlled entry point, validating arguments, performing the privileged operation and returning to user mode. Switching costs time, so I/O is batched and buffered, and user-space libraries minimise calls.", c: ["Privilege separation protects the system", "Trap switches to kernel mode at a controlled entry", "Kernel validates arguments", "Overhead motivates buffering"], k: ["Context switches flush some processor state", "Modern kernels vary in how much runs in kernel mode"], m: ["Letting user code access hardware directly"] },
  { t: "Memory allocation: stack, heap and fragmentation", p: "Compare stack and heap allocation and explain fragmentation.", d: 1, tp: "concurrency-os", tp2: "memory-systems", i: "Stack allocation is fast, automatic and scoped to function calls, with limited size and risk of overflow from deep recursion or large locals. Heap allocation is flexible, with lifetimes controlled by the programmer or garbage collector, but slower and can leak memory or fragment: external fragmentation leaves free memory split into pieces too small to use, and internal fragmentation wastes space inside allocated blocks. Allocators use size classes and pools to reduce it.", c: ["Stack is fast, scoped and limited", "Heap is flexible but slower and can leak", "External and internal fragmentation", "Size classes and pools reduce fragmentation"], k: ["Garbage collection trades pause time for safety", "Arena allocation frees many objects at once"], m: ["Returning a pointer to a stack variable"] },
  { t: "Lock-free programming and atomic operations", p: "What are atomic compare-and-swap operations and what pitfalls arise in lock-free code?", d: 3, tp: "concurrency-os", i: "Compare-and-swap atomically updates a memory location only if it still holds an expected value, letting threads retry rather than block, forming the basis of lock-free structures such as stacks and queues. Pitfalls include the ABA problem (a value changes and returns, fooling the check), memory ordering subtleties, memory reclamation of nodes other threads may still read and difficult verification, so use well-tested libraries unless performance demands otherwise.", c: ["CAS updates only if the expected value is unchanged", "Retry loops instead of blocking", "ABA problem and memory ordering", "Safe memory reclamation is hard"], k: ["Lock-free does not mean wait-free", "Contention still degrades throughput"], m: ["Writing custom lock-free structures without rigorous testing"] },
  { t: "Producer-consumer with bounded buffers", p: "Sketch a thread-safe bounded queue and explain how you avoid busy waiting.", d: 2, tp: "concurrency-os", tp2: "data-structures", i: "Protect the queue with a mutex and use two condition variables, not-full and not-empty. A producer locks, waits while the queue is full, enqueues, signals not-empty and unlocks. A consumer locks, waits while empty, dequeues, signals not-full and unlocks. Waiting threads sleep rather than spin, always re-checking conditions in loops. Alternatives are semaphores for slots and items, or lock-free ring buffers for single producer and consumer.", c: ["Mutex protects the queue", "Not-full and not-empty condition variables", "Wait in a loop re-checking the predicate", "Semaphores or lock-free ring buffers as alternatives"], k: ["Shutdown signalling must wake waiters", "Bounded size gives backpressure"], m: ["Spinning on a flag with sleep calls"] },
  // ---- Networking ----
  { t: "TCP congestion control and slow start", p: "Describe how TCP controls its sending rate and why a new connection starts slowly.", d: 2, tp: "networking", i: "TCP uses a congestion window limiting unacknowledged data. Slow start begins small and doubles each round trip until reaching a threshold or detecting loss, probing capacity without flooding. Congestion avoidance then grows linearly, and loss (timeout or duplicate acknowledgements) reduces the window multiplicatively. Modern variants such as CUBIC and BBR adapt differently. New connections therefore take several round trips to reach full speed, which is why connection reuse and larger initial windows help.", c: ["Congestion window limits data in flight", "Slow start doubles per round trip", "Linear growth then multiplicative decrease on loss", "Connection reuse avoids repeated ramp-up"], k: ["Throughput is limited by window over RTT", "BBR estimates bandwidth and RTT instead of reacting to loss"], m: ["Thinking TCP sends at full speed from the start"] },
  { t: "TCP versus UDP and when to use each", p: "When is UDP a better choice than TCP, and how does QUIC fit in?", d: 1, tp: "networking", i: "TCP provides reliable, ordered byte streams with congestion control, at the cost of handshake latency and head-of-line blocking when packets are lost. UDP provides unreliable datagrams with minimal overhead, suiting real-time media, games, DNS and custom protocols that handle loss themselves. QUIC builds reliable, multiplexed, encrypted streams on UDP, avoiding head-of-line blocking across streams and speeding connection setup, and underlies HTTP/3.", c: ["TCP: reliable, ordered, congestion controlled", "UDP: unreliable datagrams with low overhead", "UDP suits real-time and custom protocols", "QUIC adds reliability and multiplexing over UDP"], k: ["Head-of-line blocking affects TCP streams", "Firewalls may treat UDP differently"], m: ["Choosing UDP for transferring files without implementing reliability"] },
  { t: "DNS resolution and caching", p: "Walk through how DNS resolves a name and where caching happens.", d: 1, tp: "networking", i: "The client checks its local cache and the operating system resolver, then queries a recursive resolver, which, if not cached, asks a root server, then the top-level domain server, then the authoritative server for the domain, receiving the record. Each response carries a TTL, letting browsers, operating systems and resolvers cache results, reducing latency and load. Low TTLs speed up changes but increase query load, and DNSSEC authenticates answers.", c: ["Local and resolver caches first", "Root, TLD and authoritative servers", "TTL controls caching", "DNSSEC authenticates answers"], k: ["Record types include A, AAAA, CNAME and MX", "Propagation delay is cache expiry, not a broadcast"], m: ["Thinking DNS changes propagate instantly"] },
  { t: "TLS handshake and certificates", p: "Explain what the TLS handshake achieves and how certificates establish trust.", d: 2, tp: "networking", tp2: "security", i: "The client and server agree on protocol version and cipher suite, the server proves its identity with a certificate chain that the client validates against trusted root authorities (checking name, validity and revocation), and they establish shared session keys using ephemeral key exchange (Diffie-Hellman), giving forward secrecy. Application data is then encrypted and authenticated. TLS 1.3 reduces the handshake to one round trip.", c: ["Negotiate version and ciphers", "Server certificate validated against trusted roots", "Ephemeral key exchange gives forward secrecy", "Encrypted and authenticated data transfer"], k: ["Certificate name must match the host", "Private keys must be protected"], m: ["Disabling certificate validation to make errors go away"] },
  { t: "HTTP/1.1, HTTP/2 and HTTP/3 differences", p: "How do HTTP/2 and HTTP/3 improve on HTTP/1.1?", d: 2, tp: "networking", tp2: "web-apis", i: "HTTP/1.1 handles one request at a time per connection, so browsers open several connections and suffer head-of-line blocking. HTTP/2 multiplexes many streams over one TCP connection with header compression and server push, but a lost TCP packet still stalls all streams. HTTP/3 runs over QUIC, so streams are independent at the transport layer, connection setup is faster and connections survive network changes.", c: ["HTTP/1.1 one request per connection with head-of-line blocking", "HTTP/2 multiplexing and header compression", "TCP loss still blocks all HTTP/2 streams", "HTTP/3 uses QUIC for independent streams"], k: ["Fewer connections reduce handshake overhead", "Old optimisations like sprites and domain sharding become unneeded"], m: ["Keeping HTTP/1.1 workarounds under HTTP/2"] },
  { t: "NAT, firewalls and connectivity for peer-to-peer", p: "Why is it hard for two devices behind home routers to connect directly, and how do protocols handle it?", d: 3, tp: "networking", i: "NAT rewrites private addresses to a shared public one and only allows inbound traffic that matches an outbound mapping, so unsolicited connections are dropped. Peer-to-peer systems use STUN to discover public mappings, hole punching to create mappings at both ends simultaneously, and TURN relays when direct connection fails (symmetric NAT), as in WebRTC with ICE coordinating candidates. IPv6 reduces the need for NAT.", c: ["NAT only allows inbound traffic matching outbound mappings", "STUN discovers public addresses", "Hole punching and TURN relays", "ICE coordinates candidates in WebRTC"], k: ["Symmetric NAT breaks simple hole punching", "Relays cost bandwidth"], m: ["Assuming any two internet hosts can open connections to each other"] },
  { t: "Latency versus bandwidth in network performance", p: "Why can a faster connection fail to speed up page loads, and what reduces latency-bound delays?", d: 2, tp: "networking", i: "Many web interactions are small requests dominated by round-trip times: DNS, TCP and TLS handshakes, then request-response chains, so more bandwidth helps large downloads but not latency-bound sequences. Reduce latency with CDNs, connection reuse, HTTP/2 or HTTP/3, TLS 1.3, preconnect and prefetch, fewer sequential dependencies, caching and compressing data. Physical distance sets a lower bound on round-trip time.", c: ["Small requests are round-trip bound", "Handshakes and request chains add latency", "CDNs, connection reuse and modern protocols reduce it", "Distance sets a lower bound"], k: ["Bandwidth-delay product governs large transfers", "Waterfall charts show dependency chains"], m: ["Buying more bandwidth to fix slow page loads"] },
  { t: "Routing basics: BGP and OSPF", p: "Distinguish interior and exterior routing protocols and what makes BGP risky.", d: 3, tp: "networking", i: "Interior protocols such as OSPF flood link-state information within a network so every router computes shortest paths. BGP exchanges reachability between autonomous systems, with routes chosen by policy (business relationships, path length) rather than purely by metric. Because routers largely trust announcements, mistakes or malicious hijacks can redirect or blackhole traffic globally, so mitigations include prefix filtering, RPKI route validation and monitoring.", c: ["OSPF is link-state within one network", "BGP shares routes between autonomous systems by policy", "Trust-based announcements can be hijacked", "Filtering, RPKI and monitoring"], k: ["Convergence time matters during failures", "Anycast uses BGP to direct users to nearby sites"], m: ["Assuming internet routing always picks the fastest path"] },
  // ---- Security ----
  { t: "Password storage: hashing, salting and key stretching", p: "How should an application store user passwords, and why are plain hashes like SHA-256 unsuitable?", d: 2, tp: "security", i: "Store a slow, salted hash made with a purpose-built algorithm such as Argon2id, bcrypt or scrypt, with a unique random salt per user so identical passwords differ and precomputed tables fail, and a work factor tuned to cost around a hundred milliseconds. Fast hashes like SHA-256 let attackers test billions of guesses per second on GPUs after a breach. Add rate limiting, breach checks, multi-factor authentication and never store or log plaintext.", c: ["Slow memory-hard hash: Argon2id, bcrypt or scrypt", "Unique salt per user", "Tuned work factor", "Rate limiting and multi-factor authentication"], k: ["Pepper adds an extra secret held outside the database", "Upgrade hashing parameters over time"], m: ["Using a fast general-purpose hash for passwords"] },
  { t: "Cross-site scripting and output encoding", p: "What is XSS, how do the main types differ and what are the primary defences?", d: 2, tp: "security", tp2: "web-apis", i: "XSS injects attacker script that runs in a victim's browser in the site's origin, stealing sessions or acting as the user. Stored XSS persists in the database, reflected XSS comes from request parameters and DOM-based XSS arises in client-side code. The main defence is context-aware output encoding (HTML, attribute, JavaScript, URL) or frameworks that escape by default, supported by a strict Content Security Policy, HttpOnly cookies, input validation and avoiding dangerous sinks like innerHTML.", c: ["Injected script runs in the site's origin", "Stored, reflected and DOM-based types", "Context-aware output encoding", "CSP and HttpOnly cookies reduce impact"], k: ["Sanitise rich HTML with a vetted library", "Encoding must match the output context"], m: ["Relying on input filtering alone"] },
  { t: "CSRF and session security", p: "How does cross-site request forgery work and how do SameSite cookies and tokens help?", d: 2, tp: "security", i: "A malicious site causes the victim's browser to send a state-changing request to another site, which accepts it because the browser automatically attaches the user's session cookie. Defences include anti-CSRF tokens that attackers cannot read, SameSite cookie attributes that prevent cookies on cross-site requests, checking Origin headers and requiring re-authentication for sensitive actions. Safe methods like GET must not change state.", c: ["Browser attaches cookies automatically to forged requests", "Anti-CSRF tokens", "SameSite cookies and Origin checks", "Do not change state on GET"], k: ["APIs using bearer tokens in headers are not affected by cookie-based CSRF", "Login CSRF is a related issue"], m: ["Using GET requests for actions that change state"] },
  { t: "Authentication versus authorisation and common flaws", p: "Distinguish authentication from authorisation and name a flaw that arises from confusing them.", d: 1, tp: "security", i: "Authentication proves who a user is, while authorisation decides what that user may do. Broken access control, such as insecure direct object references, happens when an app checks that a user is logged in but not that they own the resource requested, letting them change an ID in the URL to read others' data. Enforce authorisation on the server for every request, deny by default and test access rules for each role.", c: ["Authentication establishes identity", "Authorisation determines permitted actions", "Insecure direct object references from missing ownership checks", "Server-side enforcement on every request"], k: ["Hiding buttons in the UI is not access control", "Least privilege limits damage"], m: ["Checking only that the user is logged in"] },
  { t: "Public key cryptography and digital signatures", p: "Explain how asymmetric cryptography provides encryption and signatures.", d: 2, tp: "security", i: "Each party has a public key shared openly and a private key kept secret. For confidentiality, data encrypted with the recipient's public key can be decrypted only with their private key. For signatures, the sender signs a hash of the message with their private key, and anyone can verify it with the public key, proving origin and integrity. Because asymmetric operations are slow, systems use them to exchange symmetric keys and encrypt bulk data with those.", c: ["Public and private key pair", "Encrypt with the recipient's public key", "Sign with the private key and verify with the public key", "Hybrid use with symmetric encryption"], k: ["Certificates bind public keys to identities", "Key management is the hard part"], m: ["Encrypting with the private key to keep data secret"] },
  { t: "OAuth 2.0 and delegated authorisation", p: "What problem does OAuth 2.0 solve and what is the role of the authorisation code flow?", d: 3, tp: "security", tp2: "web-apis", i: "OAuth lets a user grant an application limited access to their data on another service without sharing their password. In the authorisation code flow the app redirects the user to the provider to sign in and consent, receives a short-lived code at its redirect URI and exchanges it server-side (with PKCE for public clients) for an access token with specific scopes. Tokens are short lived and refreshed, and OpenID Connect adds identity on top.", c: ["Delegated access without sharing passwords", "Authorisation code exchanged for tokens", "PKCE protects public clients", "Scopes and short-lived tokens"], k: ["Validate redirect URIs and state parameters", "OAuth is authorisation, not authentication by itself"], m: ["Using the implicit flow or skipping state validation"] },
  { t: "Threat modelling with STRIDE", p: "How would you threat-model a new web service?", d: 2, tp: "security", i: "Draw a data flow diagram with components, data stores and trust boundaries, then for each element consider STRIDE: spoofing, tampering, repudiation, information disclosure, denial of service and elevation of privilege. Rate and prioritise threats, define mitigations such as authentication, integrity checks, logging, encryption, rate limiting and least privilege, and track them as work items, revisiting the model when the design changes.", c: ["Data flow diagram and trust boundaries", "STRIDE categories per element", "Prioritise threats and define mitigations", "Revisit as the design evolves"], k: ["Early modelling is cheaper than late fixes", "Abuse cases complement use cases"], m: ["Threat modelling only after the system is built"] },
  { t: "Secrets management and supply chain security", p: "How should API keys and credentials be handled in code and deployment, and what supply chain risks exist?", d: 2, tp: "security", tp2: "testing-reliability", i: "Never commit secrets to source control; load them from a secrets manager or environment at runtime, scope them with least privilege, rotate regularly and revoke on exposure, with scanning to catch leaks. Supply chain risks include malicious or vulnerable dependencies and compromised build systems, so pin and verify dependencies, use lockfiles, scan for known vulnerabilities, generate a software bill of materials and protect CI credentials and signing keys.", c: ["Keep secrets out of source control", "Secrets manager, least privilege and rotation", "Dependency pinning and vulnerability scanning", "Protect the build and signing pipeline"], k: ["Git history retains committed secrets", "Short-lived credentials limit exposure"], m: ["Committing a key and deleting it in a later commit"] },
  { t: "Buffer overflows and memory-safe languages", p: "How does a buffer overflow lead to code execution and how can it be mitigated?", d: 3, tp: "security", tp2: "concurrency-os", i: "Writing past a buffer's end overwrites adjacent memory such as return addresses or function pointers, letting an attacker redirect execution to injected or existing code. Mitigations include bounds checking, memory-safe languages, stack canaries, non-executable memory (DEP), address space layout randomisation, control-flow integrity, and fuzzing and sanitisers during development. Defence in depth matters because each mitigation can be bypassed.", c: ["Overwrite of return addresses or pointers", "Redirect execution to attacker code", "Bounds checking and memory-safe languages", "Canaries, DEP, ASLR and fuzzing"], k: ["Use-after-free and integer overflow cause similar problems", "Return-oriented programming bypasses non-executable memory"], m: ["Relying on a single mitigation"] },
  // ---- Web & APIs ----
  { t: "REST API design principles", p: "What makes a REST API well designed, and how should you handle versioning and pagination?", d: 2, tp: "web-apis", i: "Model resources with nouns and URLs, use HTTP methods with correct semantics (GET safe, PUT and DELETE idempotent), meaningful status codes and consistent error bodies, and make responses cacheable where possible. Version through the URL or headers and avoid breaking changes, paginate large collections with cursor-based pagination for stable results (offset pagination is simpler but unstable with changing data), and document with OpenAPI.", c: ["Resource-oriented URLs and correct HTTP semantics", "Status codes and consistent errors", "Versioning without breaking clients", "Cursor-based pagination and documentation"], k: ["Idempotent methods enable safe retries", "Rate limiting and authentication belong to the design"], m: ["Using verbs in URLs and returning 200 for errors"] },
  { t: "REST versus GraphQL versus gRPC", p: "Compare REST, GraphQL and gRPC and when each fits.", d: 2, tp: "web-apis", i: "REST is simple, cacheable and universally supported, but can over-fetch or need multiple round trips. GraphQL lets clients request exactly the fields they need in one query, useful for varied clients such as mobile apps, at the cost of caching complexity, query cost control and server complexity. gRPC uses binary Protocol Buffers over HTTP/2 with strong typing and streaming, efficient for internal service-to-service calls but less browser friendly.", c: ["REST: simple and cacheable", "GraphQL: client-specified queries", "gRPC: binary, typed and streaming for internal services", "Select by clients, performance and tooling"], k: ["GraphQL needs depth and cost limits", "Schemas act as contracts in all three"], m: ["Adopting GraphQL for a simple CRUD service"] },
  { t: "Browser rendering pipeline and performance", p: "Describe how a browser turns HTML, CSS and JavaScript into pixels and what causes slow loading or jank.", d: 3, tp: "web-apis", i: "The browser parses HTML into the DOM and CSS into the CSSOM, combines them into a render tree, performs layout to compute geometry, paints layers and composites them on the GPU. JavaScript can block parsing and trigger layout and repaint. Slowness comes from render-blocking CSS and scripts, large payloads and images, long main-thread tasks and layout thrashing by interleaving reads and writes of layout properties. Fixes include deferring scripts, code splitting, caching, optimising images and using transform animations.", c: ["DOM and CSSOM build the render tree", "Layout, paint and composite", "Blocking resources, long tasks and layout thrashing slow pages", "Defer scripts, split code and optimise assets"], k: ["Core Web Vitals measure user-perceived performance", "Compositor-only animations avoid layout"], m: ["Reading and writing layout properties in a loop"] },
  { t: "Web caching: ETag, Cache-Control and invalidation", p: "How do HTTP caching headers let a browser avoid downloading unchanged content?", d: 2, tp: "web-apis", tp2: "networking", i: "Cache-Control tells caches how long a response is fresh (max-age) and whether it can be shared (public, private, no-store). When stale, the client revalidates with a conditional request using ETag (If-None-Match) or Last-Modified, and the server returns 304 Not Modified without the body if unchanged. Static assets use content-hashed filenames with long max-age so new versions get new URLs, while HTML is revalidated.", c: ["Cache-Control max-age and visibility", "Conditional requests with ETag and 304 responses", "Hashed asset filenames with long caching", "Revalidate HTML"], k: ["no-cache means revalidate, not do not cache", "Vary controls cache keys"], m: ["Caching authenticated responses in shared caches"] },
  { t: "CORS and the same-origin policy", p: "What does the same-origin policy protect and how does CORS relax it safely?", d: 2, tp: "web-apis", tp2: "security", i: "The same-origin policy stops a page's scripts from reading responses from other origins, preventing malicious sites from reading your data on other sites. CORS lets a server opt in to cross-origin reads by sending Access-Control-Allow-Origin and related headers, with preflight OPTIONS requests for non-simple methods or headers. Safe configuration allows specific trusted origins, avoids wildcard with credentials and does not treat CORS as authentication.", c: ["Same-origin policy blocks cross-origin reads", "Server opts in using CORS headers", "Preflight requests for non-simple requests", "Allow specific origins and never use wildcard with credentials"], k: ["CORS is enforced by browsers, not servers", "It does not stop requests being sent, only reading responses"], m: ["Reflecting any Origin header as allowed"] },
  { t: "WebSockets, server-sent events and long polling", p: "How would you choose between WebSockets, SSE and polling for real-time updates?", d: 2, tp: "web-apis", tp2: "networking", i: "Polling is simplest and works everywhere, but wastes requests and adds latency. Server-sent events provide a one-way stream from server to browser over HTTP with automatic reconnection, suiting notifications and live feeds. WebSockets give full-duplex messaging over a persistent connection, suiting chat and collaborative apps, but need connection state management, heartbeat, scaling with sticky routing or pub/sub and fallback handling. Choose the simplest mechanism that meets the interaction needs.", c: ["Polling is simple but wasteful", "SSE for one-way streams with reconnection", "WebSockets for full-duplex interaction", "Scaling needs pub/sub and heartbeats"], k: ["Proxies and load balancers must support long-lived connections", "Backpressure matters on slow clients"], m: ["Using WebSockets where SSE or polling would do"] },
  { t: "Frontend state management and rendering efficiency", p: "How do frameworks like React avoid unnecessary re-rendering, and what makes state management hard at scale?", d: 3, tp: "web-apis", i: "UI is a function of state, and the framework re-renders when state changes, using a virtual DOM or fine-grained reactivity to update only what changed. Efficiency comes from keeping state local, memoising expensive computation and components, stable keys in lists and avoiding creating new object identities each render. At scale, shared state causes tangled data flow, so patterns centralise it with explicit updates, separate server cache state from UI state and derive values rather than duplicate them.", c: ["UI as a function of state", "Virtual DOM or fine-grained updates", "Memoisation, keys and stable references", "Centralised shared state and server-state caching"], k: ["Derived data should not be stored twice", "Over-optimising early adds complexity"], m: ["Putting all state in one global store"] },
  { t: "API pagination, filtering and consistency under change", p: "Why can offset-based pagination return duplicates or miss records, and what is the alternative?", d: 2, tp: "web-apis", tp2: "databases", i: "With offset pagination, if rows are inserted or deleted between page requests, items shift position, so a client may see duplicates or skip records, and large offsets are slow because the database scans past them. Cursor (keyset) pagination returns items after a stable ordering key such as an indexed timestamp plus ID, so pages remain consistent and efficient. It requires a deterministic sort order and does not allow jumping to arbitrary pages.", c: ["Offset shifts when data changes", "Large offsets are slow", "Cursor or keyset pagination uses a stable ordering key", "Needs a deterministic sort and limits random access"], k: ["Include a tiebreaker such as the ID", "Return an opaque cursor to clients"], m: ["Paginating by offset over rapidly changing data"] },
  // ---- Testing & reliability ----
  { t: "Test pyramid and what to test where", p: "Explain the test pyramid and why too many end-to-end tests cause problems.", d: 1, tp: "testing-reliability", i: "Many fast, isolated unit tests at the base verify logic, fewer integration tests check components working together with real dependencies, and a small number of end-to-end tests exercise critical user journeys. End-to-end tests are slow, brittle and hard to debug, so relying on them heavily produces slow feedback and flaky suites. Balance gives quick, reliable detection with confidence in the whole system.", c: ["Many unit tests at the base", "Fewer integration tests", "Few end-to-end tests for key journeys", "End-to-end tests are slow and flaky"], k: ["Test behaviour rather than implementation details", "Contract tests help between services"], m: ["Covering everything with end-to-end tests"] },
  { t: "Flaky tests and how to fix them", p: "What causes flaky tests and how do you deal with them?", d: 2, tp: "testing-reliability", i: "Common causes are shared state between tests, reliance on timing and sleeps, unordered collections, network or external services, time and randomness, and resource contention. Fix by isolating tests with clean state, replacing sleeps with explicit waits on conditions, controlling clocks and random seeds, mocking external services, running tests in random order to expose coupling and quarantining and tracking flaky tests until fixed, rather than ignoring failures.", c: ["Shared state, timing and external dependencies", "Control time and randomness", "Wait on conditions instead of sleeping", "Quarantine and fix instead of ignoring"], k: ["Flaky tests erode trust in the suite", "Reproduce with repeated runs"], m: ["Adding retries to hide flakiness"] },
  { t: "SLIs, SLOs and error budgets", p: "Explain SLIs, SLOs and error budgets and how they guide release decisions.", d: 2, tp: "testing-reliability", tp2: "systems-design", i: "A service level indicator measures a user-facing aspect such as request success rate or latency percentile, and a service level objective sets the target, for example 99.9 percent of requests succeed in a month. The error budget is the allowed unreliability (0.1 percent), spent by incidents and risky releases. When the budget is nearly used, teams slow feature releases and focus on reliability, aligning product and operations incentives with measurable user experience.", c: ["SLI measures user-facing quality", "SLO sets the target", "Error budget is the allowed failure", "Budget guides release pace and reliability work"], k: ["Percentiles capture tail latency better than averages", "SLAs are contractual and usually looser than SLOs"], m: ["Targeting 100 percent reliability"] },
  { t: "Incident response and blameless postmortems", p: "What makes an incident response effective and a postmortem useful?", d: 2, tp: "testing-reliability", i: "During an incident, assign clear roles (incident commander, communications, operations), prioritise mitigation over root cause, communicate status regularly and keep a timeline. After resolution, a blameless postmortem examines contributing factors, detection and response gaps, what worked and what did not, and produces tracked action items with owners. Blamelessness encourages honest reporting and focuses on fixing systems and processes, not individuals.", c: ["Clear roles and mitigation first", "Regular communication and timeline", "Blameless postmortem on contributing factors", "Tracked action items with owners"], k: ["Runbooks speed response", "Near misses deserve review too"], m: ["Stopping at the proximate cause and blaming an individual"] },
  { t: "Continuous integration and deployment strategies", p: "Compare blue-green, canary and rolling deployments.", d: 2, tp: "testing-reliability", i: "Rolling deployments replace instances gradually, using few extra resources but mixing versions during the rollout. Blue-green runs a full second environment and switches traffic atomically, allowing instant rollback at the cost of double capacity and database compatibility planning. Canary releases send a small percentage of traffic to the new version, monitor metrics and expand gradually, limiting blast radius. Feature flags separate deployment from release, and database migrations must be backward compatible.", c: ["Rolling replaces instances gradually", "Blue-green switches between full environments", "Canary exposes a small share first", "Feature flags and backward compatible migrations"], k: ["Automatic rollback based on health metrics", "Version skew must be handled"], m: ["Deploying a breaking schema change together with the code"] },
  { t: "Chaos engineering and resilience testing", p: "What is chaos engineering and how do you run experiments safely?", d: 3, tp: "testing-reliability", tp2: "systems-design", i: "Chaos engineering deliberately injects failures such as killed instances, latency, dropped dependencies or zone loss to test whether the system tolerates them, revealing weaknesses before real incidents. Safe practice is to define steady-state metrics, form a hypothesis, start small in a controlled scope or staging, monitor, have a quick abort, limit blast radius, and fix findings. Game days practise human response too.", c: ["Inject failures to test resilience", "Steady-state hypothesis", "Small scope, monitoring and abort conditions", "Fix findings and practise response"], k: ["Run in production only after confidence in staging", "Timeouts, retries and circuit breakers are tested"], m: ["Injecting failures with no rollback plan"] },
  { t: "Retries, timeouts and circuit breakers", p: "How do you design client retry behaviour so it helps instead of causing outages?", d: 3, tp: "testing-reliability", tp2: "web-apis", i: "Set timeouts on every remote call, retry only idempotent operations and only transient errors, use exponential backoff with jitter to avoid synchronised retry storms, cap total attempts and use retry budgets. Circuit breakers stop calling a failing dependency after a threshold, failing fast and probing periodically for recovery, and bulkheads isolate resources so one dependency cannot exhaust all threads. Propagate deadlines across calls.", c: ["Timeouts on all calls", "Retry only idempotent transient failures", "Exponential backoff with jitter and caps", "Circuit breakers and bulkheads"], k: ["Retries multiply load during outages", "Deadline propagation avoids wasted work"], m: ["Retrying immediately in a tight loop"] },
  { t: "Code review practices that improve quality", p: "What makes a code review effective, and what should reviewers focus on?", d: 1, tp: "testing-reliability", tp2: "oop-design", i: "Keep changes small and well described, automate style and static checks so humans focus on design, correctness, edge cases, error handling, security, tests and maintainability, ask questions rather than dictate, give specific and kind feedback and respond promptly. Authors self-review first and explain trade-offs. Reviews spread knowledge and catch defects early, but cannot replace testing.", c: ["Small, well-described changes", "Automate style and static checks", "Focus on design, correctness, security and tests", "Constructive, prompt feedback"], k: ["Large reviews get superficial attention", "Knowledge sharing is a main benefit"], m: ["Reviewing only for formatting issues"] },
  { t: "Property-based testing and fuzzing", p: "How do property-based testing and fuzzing find bugs that example-based tests miss?", d: 3, tp: "testing-reliability", tp2: "security", i: "Property-based testing states general properties that must hold for all inputs, such as decode(encode(x)) == x or a sorted list being ordered, and the framework generates many random inputs, shrinking failures to minimal counterexamples. Fuzzing feeds large volumes of malformed or random inputs, often guided by coverage feedback, to find crashes, hangs and memory errors, especially in parsers. Both explore input spaces humans rarely think to test.", c: ["Properties checked on generated inputs", "Shrinking to minimal failing cases", "Fuzzing with coverage feedback finds crashes", "Strong for parsers and serialisation"], k: ["Writing good properties is the main skill", "Seeds should be saved to reproduce failures"], m: ["Relying only on a handful of hand-picked examples"] },
];
